package local.tvmorph.tv;
import android.app.*;import android.widget.*;import android.graphics.*;import android.content.*;import java.util.*;import java.net.*;import java.security.*;import org.json.*;import local.cleartv.mobile.LanHttp;
/** Short lived, one-use capability scoped only to adding an IPTV account. */
final class SubscriptionSetup {
 private static String secret,authority;private static long until;private static boolean busy;private static AlertDialog dialog;
 private static String address()throws Exception{Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();String fallback=null;while(all!=null&&all.hasMoreElements()){NetworkInterface n=all.nextElement();if(!n.isUp()||n.isLoopback()||n.isVirtual())continue;Enumeration<InetAddress> a=n.getInetAddresses();while(a.hasMoreElements()){InetAddress ip=a.nextElement();if(!(ip instanceof Inet4Address)||ip.isLoopbackAddress()||ip.isLinkLocalAddress())continue;if(ip.isSiteLocalAddress())return ip.getHostAddress();if(fallback==null)fallback=ip.getHostAddress();}}if(fallback!=null)return fallback;throw new Exception("Local network unavailable");}
 static void show(Activity activity){try{if(busy)throw new Exception();if(dialog!=null&&dialog.isShowing())dialog.dismiss();if(!PhoneLinkServer.running())throw new Exception();final String key;final String url;synchronized(SubscriptionSetup.class){byte[] bytes=new byte[24];new SecureRandom().nextBytes(bytes);StringBuilder hex=new StringBuilder();for(byte b:bytes)hex.append(String.format(Locale.US,"%02x",b&255));secret=key=hex.toString();until=android.os.SystemClock.elapsedRealtime()+300000;busy=false;authority=address()+":"+PhoneLinkServer.port();url="http://"+authority+"/subscription-setup#"+key;}
 LinearLayout box=new LinearLayout(activity);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(28,20,28,20);ImageView image=new ImageView(activity);com.google.zxing.common.BitMatrix matrix=new com.google.zxing.qrcode.QRCodeWriter().encode(url,com.google.zxing.BarcodeFormat.QR_CODE,420,420);Bitmap bitmap=Bitmap.createBitmap(420,420,Bitmap.Config.ARGB_8888);for(int y=0;y<420;y++)for(int x=0;x<420;x++)bitmap.setPixel(x,y,matrix.get(x,y)?Color.BLACK:Color.WHITE);image.setImageBitmap(bitmap);box.addView(image,new LinearLayout.LayoutParams(-1,420));TextView text=new TextView(activity);text.setText(UiSettings.text(activity,"امسح الكود بكاميرا الموبايل، اكتب الاشتراك واضغط ربط. الموبايل والتلفزيون على نفس الشبكة. صالح ٥ دقائق.","Scan with your phone camera, enter your subscription and connect. Use the same Wi-Fi. Valid for 5 minutes."));text.setTextSize(18);box.addView(text);dialog=new AlertDialog.Builder(activity).setTitle(UiSettings.text(activity,"إضافة اشتراك من الموبايل","Add subscription from phone")).setView(box).setNegativeButton(UiSettings.text(activity,"إغلاق","Close"),null).create();dialog.setOnDismissListener(d->{synchronized(SubscriptionSetup.class){if(key.equals(secret))secret=null;}if(dialog==d)dialog=null;bitmap.recycle();});dialog.show();
 }catch(Exception e){Toast.makeText(activity,UiSettings.text(activity,"تعذّر إنشاء الربط. تأكد من الشبكة وافتح رئيسية Morph TV أولًا.","Could not start setup. Check the network and open Morph TV home first."),1).show();}}
 static LanHttp.Response handle(Context context,String method,String path,Map<String,String> headers,byte[] body)throws Exception{
 if(method.equals("GET")&&path.equals("/subscription-setup")){try(java.io.InputStream input=context.getAssets().open("iptv/subscription-setup.html")){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1)bytes.write(buffer,0,n);LanHttp.Response response=new LanHttp.Response(200,"text/html; charset=utf-8",bytes.toByteArray());response.headers.put("Referrer-Policy","no-referrer");response.headers.put("Content-Security-Policy","default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; form-action 'none'; frame-ancestors 'none'");return response;}}
 if(!path.equals("/subscription-connect"))return null;
 if(!method.equals("POST")||body.length>16000)return new LanHttp.Response(400,"application/json","{}".getBytes("UTF-8"));JSONObject request=new JSONObject(new String(body,"UTF-8"));String key=request.optString("key");synchronized(SubscriptionSetup.class){if(secret==null||android.os.SystemClock.elapsedRealtime()>until||!authority.equals(headers.get("host"))||!MessageDigest.isEqual(secret.getBytes("UTF-8"),key.getBytes("UTF-8")))return new LanHttp.Response(401,"application/json","{\"error\":\"الرابط انتهى. افتح QR جديد من التلفزيون.\"}".getBytes("UTF-8"));if(busy)return new LanHttp.Response(409,"application/json","{\"error\":\"جاري الربط…\"}".getBytes("UTF-8"));busy=true;}
 try{JSONObject result=IptvStore.get(context).connect(request.getJSONObject("account"));synchronized(SubscriptionSetup.class){secret=null;busy=false;}new android.os.Handler(android.os.Looper.getMainLooper()).post(()->{if(dialog!=null&&dialog.isShowing())dialog.dismiss();IptvActivity.subscriptionConnected();Toast.makeText(context,UiSettings.text(context,"تم ربط الاشتراك من الموبايل","Subscription connected from phone"),1).show();});return LanHttp.Response.json("{\"connected\":true}");}catch(Exception e){synchronized(SubscriptionSetup.class){busy=false;}return LanHttp.Response.json(new JSONObject().put("error",UiSettings.text(context,"تعذّر الربط. راجع البيانات وصلاحية الاشتراك.","Connection failed. Check subscription details and validity.")).toString());}
 }
}
